    out->filter_primed_this_cycle = 0;
    out->field_magnitude_t = 0.0;
    out->rate_norm_t_s = 0.0;
    out->rate_t_s = zero_v;
    out->dipole_a_m2 = zero_v;
    return;
}

/* Invalid configuration or flags handled as a rejected sample (no immediate FAULT). */
if (!cfg_ok || !flags_ok) {
    st->good = 0U;
    st->bad += 1U;
    if (st->bad >= cfg->max_bad) {
        st->mode = DT_FAULT;
    }
    out->mode = st->mode;
    out->good = st->good;
    out->bad = st->bad;
    out->saturation_mask = 0U;
    out->slew_mask = 0U;
    out->filter_primed_this_cycle = 0;
    out->field_magnitude_t = 0.0;
    out->rate_norm_t_s = 0.0;
    out->rate_t_s = zero_v;
    out->dipole_a_m2 = zero_v;
    return;
}

field = *in->field_body_t;
mag = adcs_vec3_norm(&field);

/* Each accepted field sample is processed with adcs_bdot_update on a trial copy
   of the persistent filter. */
trial = st->filter;
rate = zero_v;
st_upd = adcs_bdot_update(&trial, &field, in->time_s, cfg->filter_alpha, &rate);

accepted = 1;
primed_this = 0;

if (!in->valid || !adcs_is_finite_vec3(&field) || !isfinite(in->time_s)) {
    accepted = 0;
}
/* Accept field magnitudes only within [minimum_field_t, maximum_field_t]. */
if (accepted && (!(mag >= cfg->minimum_field_t) || !(mag <= cfg->maximum_field_t))) {
    accepted = 0;
}
/* A sample for which adcs_bdot_update fails handled as rejected. */
if (st_upd != ADCS_OK) {
    accepted = 0;
}

if (accepted) {
    if (!st->filter.initialized) {
        /* The first sample primes the differentiator. */
        primed_this = 1;
    } else {
        dt = in->time_s - st->filter.previous_time_s;
        /* If the interval since the previous accepted sample exceeds
           max_sample_gap_s, reset and re-prime instead of differentiating across the gap. */
        if (!isfinite(dt) || (dt <= 0.0) || (dt > cfg->max_sample_gap_s)) {
            st->filter.initialized = 0;
            trial = st->filter;
            rate = zero_v;
            st_upd = adcs_bdot_update(&trial, &field, in->time_s, cfg->filter_alpha, &rate);
            if (st_upd != ADCS_OK) {
                accepted = 0;
            } else {
                primed_this = 1;
            }
        }
    }
}

if (!accepted) {
    /* Rejected samples preserve filter and previous dipole internally, publish zero,
       clear good evidence, increment bad, and latch FAULT at max_bad. */
    st->good = 0U;
    st->bad += 1U;
    if (st->bad >= cfg->max_bad) {
        st->mode = DT_FAULT;
    }
    out->mode = st->mode;
    out->good = st->good;
    out->bad = st->bad;
    out->saturation_mask = 0U;
    out->slew_mask = 0U;
    out->filter_primed_this_cycle = 0;
    out->field_magnitude_t = mag;
    out->rate_norm_t_s = 0.0;
    out->rate_t_s = zero_v;
    out->dipole_a_m2 = zero_v;
    return;
}

/* A priming or re-priming cycle sets mode COARSE, clears good, publishes zero rate
   and dipole, and sets filter_primed_this_cycle=1. */
if (primed_this) {
    st->filter = trial;
    st->filtered_rate_t_s = zero_v;
    st->mode = DT_COARSE;
    st->good = 0U;
    st->previous_dipole_a_m2 = zero_v;
    out->mode = DT_COARSE;
    out->good = 0U;
    out->bad = st->bad;
    out->saturation_mask = 0U;
    out->slew_mask = 0U;
    out->filter_primed_this_cycle = 1;
    out->field_magnitude_t = mag;
    out->rate_norm_t_s = 0.0;
    out->rate_t_s = zero_v;
    out->dipole_a_m2 = zero_v;
    return;
}

/* Commit accepted non-priming sample. */
st->filter = trial;
st->filtered_rate_t_s = rate;
{
    double rn = adcs_vec3_norm(&st->filtered_rate_t_s);

    /* COARSE uses coarse_gain and enters FINE when filtered rate <= fine_enter_rate_t_s. */
    if (st->mode == DT_COARSE) {
        if (rn <= cfg->fine_enter_rate_t_s) {
            st->mode = DT_FINE;
        } else {
            /* No action: stay in COARSE. */
        }
    } else if (st->mode == DT_FINE) {
        /* FINE returns COARSE at fine_exit_rate_t_s. */
        if (rn >= cfg->fine_exit_rate_t_s) {
            st->mode = DT_COARSE;
        } else {
            /* No action: stay in FINE. */
        }
    } else {
        /* No action: mode not in an active coarse/fine state. */
    }

    /* In either active mode, required_good consecutive rates <= stop_rate_t_s enter COMPLETE. */
    if ((st->mode == DT_COARSE) || (st->mode == DT_FINE)) {
        if (rn <= cfg->stop_rate_t_s) {
            st->good += 1U;
            if (st->good >= cfg->required_good) {
                st->mode = DT_COMPLETE;
            }
        } else {
            st->good = 0U;
        }
    }
}

/* COMPLETE commands zero and restarts in FINE for rate >= restart_rate_t_s but below
   fine_exit, or COARSE at/above fine_exit. */
if (st->mode == DT_COMPLETE) {
    double rn = adcs_vec3_norm(&st->filtered_rate_t_s);
    out->dipole_a_m2 = zero_v;
    out->saturation_mask = 0U;
    out->slew_mask = 0U;
    st->previous_dipole_a_m2 = zero_v;
    st->good = 0U;
    if (rn >= cfg->fine_exit_rate_t_s) {
        st->mode = DT_COARSE;
    } else if (rn >= cfg->restart_rate_t_s) {
        st->mode = DT_FINE;
    } else {
        /* Rate below restart threshold: stay in COMPLETE. */
    }
    out->mode = st->mode;
    out->good = st->good;
    out->bad = st->bad;
    out->filter_primed_this_cycle = 0;
    out->field_magnitude_t = mag;
    out->rate_norm_t_s = rn;
    out->rate_t_s = st->filtered_rate_t_s;
    return;
}

/* Generate dipole with adcs_bdot_dipole. */
{
    adcs_actuator_command_t cmd;
    adcs_status_t dres;
    double prev[3], vals[3];
    uint32_t sat_mask, slew_mask;
    uint32_t k;

    gain = (st->mode == DT_FINE) ? cfg->fine_gain_a_m2_s_t : cfg->coarse_gain_a_m2_s_t;
    dres = adcs_bdot_dipole(&field, &st->filtered_rate_t_s, gain, cfg->max_dipole_a_m2, &cmd);
    if (dres != ADCS_OK) {
        cmd.command = zero_v;
        cmd.saturated_axes = 0U;
    }

    prev[0] = st->previous_dipole_a_m2.x;
    prev[1] = st->previous_dipole_a_m2.y;
    prev[2] = st->previous_dipole_a_m2.z;
    vals[0] = cmd.command.x;
    vals[1] = cmd.command.y;
    vals[2] = cmd.command.z;

    /* Limit each component change from the previous published dipole by
       max_dipole_slew_a_m2_per_cycle. */
    slew_mask = 0U;
    for (k = 0U; k < 3U; k++) {
        double d = vals[k] - prev[k];
        if (d > cfg->max_dipole_slew_a_m2_per_cycle) {
            vals[k] = prev[k] + cfg->max_dipole_slew_a_m2_per_cycle;
            slew_mask |= (uint32_t)(1U << k);
        } else if (d < -cfg->max_dipole_slew_a_m2_per_cycle) {
            vals[k] = prev[k] - cfg->max_dipole_slew_a_m2_per_cycle;
            slew_mask |= (uint32_t)(1U << k);
        }
    }

    /* Publish physical saturation and slew masks separately. */
    sat_mask = cmd.saturated_axes;
    for (k = 0U; k < 3U; k++) {
        if (fabs(vals[k]) > cfg->max_dipole_a_m2) {
            vals[k] = copysign(cfg->max_dipole_a_m2, vals[k]);
            sat_mask |= (uint32_t)(1U << k);
        }
    }

    st->previous_dipole_a_m2 = (adcs_vec3_t){vals[0], vals[1], vals[2]};

    out->mode = st->mode;
    out->good = st->good;
    out->bad = st->bad;
    out->saturation_mask = sat_mask;
    out->slew_mask = slew_mask;
    out->filter_primed_this_cycle = 0;
    out->field_magnitude_t = mag;
    out->rate_norm_t_s = adcs_vec3_norm(&st->filtered_rate_t_s);
    out->rate_t_s = st->filtered_rate_t_s;
    out->dipole_a_m2 = st->previous_dipole_a_m2;
}

