dt_mode_t prev_mode;
adcs_bdot_state_t trial_filter;
adcs_vec3_t trial_rate, field_rate, raw_dipole, limited_dipole, delta;
adcs_actuator_command_t cmd;
adcs_status_t st;
unint32 i;
double mag, rate_norm, gap, slew, dv, gain;
int sample_ok, did_reprime, reject, cfg_ok;

/* --- Configuration validity (rejected-sample-grade, not immediate fault). --- */
cfg_ok = 1;
if ((dt_input.enable != 0) && (dt_input.enable != 1)) cfg_ok = 0;
if ((dt_input.valid != 0) && (dt_input.valid != 1)) cfg_ok = 0;
if (!(dt_config.filter_alpha >= 0.0 && dt_config.filter_alpha <= 1.0)) cfg_ok = 0;
if (!(dt_config.coarse_gain_a_m2_s_t >= 0.0)) cfg_ok = 0;
if (!(dt_config.fine_gain_a_m2_s_t >= 0.0)) cfg_ok = 0;
if (!(dt_config.max_dipole_a_m2 > 0.0)) cfg_ok = 0;
if (!(dt_config.max_dipole_slew_a_m2_per_cycle > 0.0)) cfg_ok = 0;
if (!(dt_config.minimum_field_t > 0.0)) cfg_ok = 0;
if (!(dt_config.maximum_field_t > 0.0)) cfg_ok = 0;
if (!(dt_config.max_sample_gap_s > 0.0)) cfg_ok = 0;
if (!(dt_config.required_good >= 1U && dt_config.required_good <= 20U)) cfg_ok = 0;
if (!(dt_config.max_bad >= 1U && dt_config.max_bad <= 20U)) cfg_ok = 0;
if (!(dt_config.stop_rate_t_s < dt_config.restart_rate_t_s &&
      dt_config.restart_rate_t_s <= dt_config.fine_enter_rate_t_s &&
      dt_config.fine_enter_rate_t_s < dt_config.fine_exit_rate_t_s)) cfg_ok = 0;

if (dt_input.enable == 0) {
    dt_state.mode = DT_OFF;
    dt_state.good = 0U;
    dt_state.bad = 0U;
    dt_state.filter.initialized = 0;
    dt_state.filter.previous_field_t = (adcs_vec3_t){0, 0, 0};
    dt_state.filter.previous_time_s = 0.0;
    dt_state.filtered_rate_t_s = (adcs_vec3_t){0, 0, 0};
    dt_state.previous_dipole_a_m2 = (adcs_vec3_t){0, 0, 0};
    dt_output.mode = DT_OFF;
    dt_output.good = 0U;
    dt_output.bad = 0U;
    dt_output.saturation_mask = 0U;
    dt_output.slew_mask = 0U;
    dt_output.filter_primed_this_cycle = 0;
    dt_output.field_magnitude_t = 0.0;
    dt_output.rate_norm_t_s = 0.0;
    dt_output.rate_t_s = (adcs_vec3_t){0, 0, 0};
    dt_output.dipole_a_m2 = (adcs_vec3_t){0, 0, 0};
    return;
}

/* --- Sample acceptance. --- */
sample_ok = 1;
if (cfg_ok == 0) sample_ok = 0;
if (dt_input.enable != 1) sample_ok = 0;
if (dt_input.valid != 1) sample_ok = 0;
if (dt_input.field_body_t == NULL) sample_ok = 0;
if (sample_ok != 0) {
    if (!isfinite(dt_input.time_s)) sample_ok = 0;
}
if (sample_ok != 0) {
    if (!adcs_is_finite_vec3(dt_input.field_body_t)) sample_ok = 0;
}
mag = 0.0;
if (sample_ok != 0) {
    mag = adcs_vec3_norm(dt_input.field_body_t);
    if (!(mag >= dt_config.minimum_field_t && mag <= dt_config.maximum_field_t))
        sample_ok = 0;
}

if (sample_ok == 0) {
    dt_state.good = 0U;
    dt_state.bad += 1U;
    if (dt_state.bad >= dt_config.max_bad) dt_state.mode = DT_FAULT;
    dt_output.mode = dt_state.mode;
    dt_output.good = dt_state.good;
    dt_output.bad = dt_state.bad;
    dt_output.saturation_mask = 0U;
    dt_output.slew_mask = 0U;
    dt_output.filter_primed_this_cycle = 0;
    dt_output.field_magnitude_t = 0.0;
    dt_output.rate_norm_t_s = 0.0;
    dt_output.rate_t_s = (adcs_vec3_t){0, 0, 0};
    dt_output.dipole_a_m2 = (adcs_vec3_t){0, 0, 0};
    return;
}

/* --- Trial copy of persistent filter; detect prime/re-prime. --- */
trial_filter = dt_state.filter;
did_reprime = 0;
if (!trial_filter.initialized) {
    did_reprime = 1;
} else {
    gap = dt_input.time_s - trial_filter.previous_time_s;
    if (!isfinite(gap) || gap > dt_config.max_sample_gap_s) did_reprime = 1;
}

reject = 0;
if (did_reprime) {
    st = adcs_bdot_update(&trial_filter, dt_input.field_body_t, dt_input.time_s,
                          0.0, &trial_rate);
} else {
    st = adcs_bdot_update(&trial_filter, dt_input.field_body_t, dt_input.time_s,
                          dt_config.filter_alpha, &trial_rate);
}
if (st != ADCS_OK) reject = 1;

if (reject) {
    dt_state.good = 0U;
    dt_state.bad += 1U;
    if (dt_state.bad >= dt_config.max_bad) dt_state.mode = DT_FAULT;
    dt_output.mode = dt_state.mode;
    dt_output.good = dt_state.good;
    dt_output.bad = dt_state.bad;
    dt_output.saturation_mask = 0U;
    dt_output.slew_mask = 0U;
    dt_output.filter_primed_this_cycle = 0;
    dt_output.field_magnitude_t = 0.0;
    dt_output.rate_norm_t_s = 0.0;
    dt_output.rate_t_s = (adcs_vec3_t){0, 0, 0};
    dt_output.dipole_a_m2 = (adcs_vec3_t){0, 0, 0};
    return;
}

if (did_reprime) {
    dt_state.filter = trial_filter;
    dt_state.mode = DT_COARSE;
    dt_state.good = 0U;
    dt_state.bad = 0U;
    dt_state.filtered_rate_t_s = (adcs_vec3_t){0, 0, 0};
    dt_state.previous_dipole_a_m2 = (adcs_vec3_t){0, 0, 0};
    dt_output.mode = DT_COARSE;
    dt_output.good = 0U;
    dt_output.bad = 0U;
    dt_output.saturation_mask = 0U;
    dt_output.slew_mask = 0U;
    dt_output.filter_primed_this_cycle = 1;
    dt_output.field_magnitude_t = mag;
    dt_output.rate_norm_t_s = 0.0;
    dt_output.rate_t_s = (adcs_vec3_t){0, 0, 0};
    dt_output.dipole_a_m2 = (adcs_vec3_t){0, 0, 0};
    return;
}

dt_state.filter = trial_filter;
dt_state.filtered_rate_t_s = trial_rate;
field_rate = trial_rate;
rate_norm = adcs_vec3_norm(&field_rate);

prev_mode = dt_state.mode;
if (prev_mode == DT_OFF) dt_state.mode = DT_COARSE;

if (dt_state.mode == DT_COARSE) {
    if (rate_norm <= dt_config.fine_enter_rate_t_s) dt_state.mode = DT_FINE;
} else if (dt_state.mode == DT_FINE) {
    if (rate_norm >= dt_config.fine_exit_rate_t_s) dt_state.mode = DT_COARSE;
} else if (dt_state.mode == DT_COMPLETE) {
    if (rate_norm >= dt_config.fine_exit_rate_t_s) {
        dt_state.mode = DT_COARSE;
    } else if (rate_norm >= dt_config.restart_rate_t_s) {
        dt_state.mode = DT_FINE;
    }
}

if (dt_state.mode == DT_COARSE || dt_state.mode == DT_FINE) {
    if (rate_norm <= dt_config.stop_rate_t_s) {
        if (dt_state.good < dt_config.required_good) dt_state.good += 1U;
        if (dt_state.good >= dt_config.required_good) dt_state.mode = DT_COMPLETE;
    } else {
        dt_state.good = 0U;
    }
} else if (dt_state.mode == DT_COMPLETE) {
    dt_state.good = 0U;
}

dt_output.saturation_mask = 0U;
dt_output.slew_mask = 0U;
raw_dipole = (adcs_vec3_t){0, 0, 0};

if (dt_state.mode == DT_COMPLETE) {
    dt_state.previous_dipole_a_m2 = (adcs_vec3_t){0, 0, 0};
    dt_output.dipole_a_m2 = (adcs_vec3_t){0, 0, 0};
} else if (dt_state.mode == DT_COARSE || dt_state.mode == DT_FINE) {
    gain = (dt_state.mode == DT_COARSE) ? dt_config.coarse_gain_a_m2_s_t
                                        : dt_config.fine_gain_a_m2_s_t;
    st = adcs_bdot_dipole(dt_input.field_body_t, &field_rate, gain,
                          dt_config.max_dipole_a_m2, &cmd);
    if (st == ADCS_OK) {
        raw_dipole = cmd.command;
        dt_output.saturation_mask = cmd.saturated_axes;
    } else {
        raw_dipole = (adcs_vec3_t){0, 0, 0};
        dt_output.saturation_mask = 0U;
    }
    slew = dt_config.max_dipole_slew_a_m2_per_cycle;
    delta = adcs_vec3_sub(&raw_dipole, &dt_state.previous_dipole_a_m2);
    if (delta.x > slew) { delta.x = slew; dt_output.slew_mask |= 1U; }
    if (delta.x < -slew) { delta.x = -slew; dt_output.slew_mask |= 1U; }
    if (delta.y > slew) { delta.y = slew; dt_output.slew_mask |= 2U; }
    if (delta.y < -slew) { delta.y = -slew; dt_output.slew_mask |= 2U; }
    if (delta.z > slew) { delta.z = slew; dt_output.slew_mask |= 4U; }
    if (delta.z < -slew) { delta.z = -slew; dt_output.slew_mask |= 4U; }
    limited_dipole = adcs_vec3_add(&dt_state.previous_dipole_a_m2, &delta);
    dv = limited_dipole.x;
    if (dv > dt_config.max_dipole_a_m2) { dv = dt_config.max_dipole_a_m2; dt_output.saturation_mask |= 1U; }
    if (dv < -dt_config.max_dipole_a_m2) { dv = -dt_config.max_dipole_a_m2; dt_output.saturation_mask |= 1U; }
    limited_dipole.x = dv;
    dv = limited_dipole.y;
    if (dv > dt_config.max_dipole_a_m2) { dv = dt_config.max_dipole_a_m2; dt_output.saturation_mask |= 2U; }
    if (dv < -dt_config.max_dipole_a_m2) { dv = -dt_config.max_dipole_a_m2; dt_output.saturation_mask |= 2U; }
    limited_dipole.y = dv;
    dv = limited_dipole.z;
    if (dv > dt_config.max_dipole_a_m2) { dv = dt_config.max_dipole_a_m2; dt_output.saturation_mask |= 4U; }
    if (dv < -dt_config.max_dipole_a_m2) { dv = -dt_config.max_dipole_a_m2; dt_output.saturation_mask |= 4U; }
    limited_dipole.z = dv;
    dt_state.previous_dipole_a_m2 = limited_dipole;
    dt_output.dipole_a_m2 = limited_dipole;
} else {
    dt_output.dipole_a_m2 = (adcs_vec3_t){0, 0, 0};
}

dt_output.mode = dt_state.mode;
dt_output.good = dt_state.good;
dt_output.bad = dt_state.bad;
dt_output.filter_primed_this_cycle = 0;
dt_output.field_magnitude_t = mag;
dt_output.rate_norm_t_s = rate_norm;
dt_output.rate_t_s = field_rate;
(void)i;

