    dt_state.mode = DT_COARSE;
    dt_state.good = 0U;
    dt_state.previous_dipole_a_m2 = (adcs_vec3_t){0.0, 0.0, 0.0};
    dt_output.mode = DT_COARSE;
    dt_output.good = 0U;
    dt_output.bad = dt_state.bad;
    dt_output.saturation_mask = 0U;
    dt_output.slew_mask = 0U;
    dt_output.filter_primed_this_cycle = 1;
    dt_output.field_magnitude_t = field_mag;
    dt_output.rate_norm_t_s = 0.0;
    dt_output.rate_t_s = (adcs_vec3_t){0.0, 0.0, 0.0};
    dt_output.dipole_a_m2 = (adcs_vec3_t){0.0, 0.0, 0.0};
    return;
}

/* State machine + dipole command. */
{
    double rate_norm = adcs_vec3_norm(&trial_rate);
    adcs_vec3_t cmd = {0.0, 0.0, 0.0};
    uint32_t sat_mask = 0U;
    uint32_t slew_mask = 0U;

    switch (dt_state.mode) {
    case DT_COARSE:
        if (rate_norm <= dt_config.fine_enter_rate_t_s) {
            dt_state.mode = DT_FINE;
        }
        if (dt_state.mode == DT_COARSE || dt_state.mode == DT_FINE) {
            if (rate_norm <= dt_config.stop_rate_t_s) {
                if (dt_state.good < 0xFFFFFFFFU) dt_state.good += 1U;
                if (dt_state.good >= dt_config.required_good) {
                    dt_state.mode = DT_COMPLETE;
                    dt_state.good = 0U;
                }
            } else {
                dt_state.good = 0U;
            }
        }
        break;
    case DT_FINE:
        if (rate_norm >= dt_config.fine_exit_rate_t_s) {
            dt_state.mode = DT_COARSE;
        }
        if (dt_state.mode == DT_COARSE || dt_state.mode == DT_FINE) {
            if (rate_norm <= dt_config.stop_rate_t_s) {
                if (dt_state.good < 0xFFFFFFFFU) dt_state.good += 1U;
                if (dt_state.good >= dt_config.required_good) {
                    dt_state.mode = DT_COMPLETE;
                    dt_state.good = 0U;
                }
            } else {
                dt_state.good = 0U;
            }
        }
        break;
    case DT_COMPLETE:
        if (rate_norm >= dt_config.fine_exit_rate_t_s) {
            dt_state.mode = DT_COARSE;
            dt_state.good = 0U;
        } else if (rate_norm >= dt_config.restart_rate_t_s) {
            dt_state.mode = DT_FINE;
            dt_state.good = 0U;
        } else {
            /* below restart: hold COMPLETE */
            dt_state.mode = DT_COMPLETE;
            dt_state.good = 0U;
        }
        break;
    default:
        break;
    }

    if (dt_state.mode == DT_COMPLETE) {
        cmd = (adcs_vec3_t){0.0, 0.0, 0.0};
        dt_state.previous_dipole_a_m2 = cmd;
        sat_mask = 0U;
        slew_mask = 0U;
    } else if (dt_state.mode == DT_COARSE || dt_state.mode == DT_FINE) {
        double gain = (dt_state.mode == DT_COARSE) ? dt_config.coarse_gain_a_m2_s_t
                                                   : dt_config.fine_gain_a_m2_s_t;
        adcs_actuator_command_t dipole_cmd;
        adcs_status_t st = adcs_bdot_dipole(&field, &trial_rate, gain,
                                            dt_config.max_dipole_a_m2, &dipole_cmd);
        if (st == ADCS_OK) {
            cmd = dipole_cmd.command;
            sat_mask = dipole_cmd.saturated_axes;
        } else {
            cmd = (adcs_vec3_t){0.0, 0.0, 0.0};
            sat_mask = 0U;
        }
        {
            double prev[3], cur[3], lim;
            int i;
            prev[0] = dt_state.previous_dipole_a_m2.x;
            prev[1] = dt_state.previous_dipole_a_m2.y;
            prev[2] = dt_state.previous_dipole_a_m2.z;
            cur[0] = cmd.x;
            cur[1] = cmd.y;
            cur[2] = cmd.z;
            lim = dt_config.max_dipole_slew_a_m2_per_cycle;
            for (i = 0; i < 3; ++i) {
                double d = cur[i] - prev[i];
                if (d > lim) {
                    d = lim;
                    slew_mask |= (uint32_t)(1U << i);
                } else if (d < -lim) {
                    d = -lim;
                    slew_mask |= (uint32_t)(1U << i);
                } else { /* within slew limit */ }
                cur[i] = prev[i] + d;
            }
            cmd = (adcs_vec3_t){cur[0], cur[1], cur[2]};
        }
        dt_state.previous_dipole_a_m2 = cmd;
    } else {
        cmd = (adcs_vec3_t){0.0, 0.0, 0.0};
        dt_state.previous_dipole_a_m2 = cmd;
        sat_mask = 0U;
        slew_mask = 0U;
    }

    dt_output.mode = dt_state.mode;
    dt_output.good = dt_state.good;
    dt_output.bad = dt_state.bad;
    dt_output.saturation_mask = sat_mask;
    dt_output.slew_mask = slew_mask;
    dt_output.filter_primed_this_cycle = 0;
    dt_output.field_magnitude_t = field_mag;
    dt_output.rate_norm_t_s = rate_norm;
    dt_output.rate_t_s = trial_rate;
    dt_output.dipole_a_m2 = cmd;
}
